class _FraudModel:
    def __init__(self, booster):
        self._booster = booster
        bi = booster.attr("best_iteration")
        self.best_iteration = int(bi) if bi is not None else booster.num_boosted_rounds() - 1

    def get_booster(self):
        return self._booster

    def set_params(self, **params):
        self._booster.set_param(params)
        return self

    def get_params(self, deep=True):
        return {"device": "cpu"}


def _load():
    raw = zlib.decompress(base64.b64decode("".join(_MODEL_B64.split())))
    booster = xgb.Booster()
    booster.load_model(bytearray(raw))
    booster.set_param({"device": "cpu"})
    return _FraudModel(booster)


model = _load()
